<template><el-dialog title="Purchase Preview" :visible="visible" width="700px" :close-on-click-modal="false" @close="$emit('update:visible',false)"><el-alert title="Demo payment. Channel prices and benefits are sample policies." type="info" :closable="false"/><el-form label-width="140px" class="compact-form" :disabled="busy"><el-form-item label="User"><el-select v-model="selectedUser" @change="clear"><el-option v-for="u in users" :key="u.id" :value="u.id" :label="u.name"/></el-select></el-form-item><el-form-item label="Product"><el-select v-model="productId" @change="selectProduct"><el-option v-for="p in products" :key="p.id" :value="p.id" :label="p.name"/></el-select></el-form-item><el-form-item label="SKU"><el-select v-model="skuId" @change="clear"><el-option v-for="sku in skus" :key="sku.id" :value="sku.id" :label="sku.channel+' · '+money(sku.priceCents,sku.currency)"/></el-select></el-form-item><el-form-item label="Payment outcome"><el-select v-model="outcome" @change="clear"><el-option label="Payment and fulfillment succeed" value="succeeded"/><el-option label="Payment fails · no benefits" value="failed"/><el-option label="Paid · fulfillment fails · retry from Orders" value="fulfillment_failed"/></el-select></el-form-item></el-form>
<div v-if="quote" class="quote-card"><h3>{{ quote.product.name }} · {{ money(quote.sku.priceCents,quote.sku.currency) }}</h3><dl class="read-detail"><dt>Product snapshot</dt><dd>v{{ quote.productVersion }} · {{ quote.sku.id }}</dd><template v-if="quote.suit"><dt>Suit snapshot</dt><dd>{{ quote.suit.config.name }} v{{ quote.suit.version }}</dd><dt>Original subscription time zone</dt><dd>{{ quote.subscriptionTimeZone }}</dd><dt>Membership period</dt><dd>{{ dateTime(quote.startsAt) }} → {{ dateTime(quote.expiresAtMembership) }}</dd></template><dt>Credits</dt><dd v-if="Array.isArray(quote.credits)"><p v-for="grant in quote.credits" :key="grant.creditType">{{ creditGrantLabel(grant) }}</p><span v-if="!quote.credits.length">No credit grants</span></dd><dd v-else>{{ quote.credits.amount }} · {{ quote.credits.validityDays===null ? "No expiry" : quote.credits.validityDays+" days after each issue" }} <span v-if="quote.suit">· {{ quote.credits.cadence }}</span></dd><dt>Quote expires</dt><dd>{{ dateTime(quote.expiresAt) }}</dd></dl><p class="field-help">Current policy: upgrades start immediately with a new cycle. Settlement is still undefined, so no upgrade payment is taken. Historical changes retain their purchased rules. Purchased credits never expire.</p></div>
<el-alert v-if="result" :title="'Payment: '+result.status+' · Fulfillment: '+result.fulfillment" :type="result.fulfillment==='completed'?'success':'warning'" :closable="false"/><p v-if="error" class="inline-error">{{ error }}</p><span slot="footer"><el-button @click="$emit('update:visible',false)">Close</el-button><el-button v-if="!quote && !result" type="primary" :loading="busy" :disabled="!selectedUser||!skuId" @click="review">Review Quote</el-button><el-button v-if="quote && !result" type="success" :loading="busy" @click="confirm">Confirm Demo Payment</el-button><el-button v-if="result" type="primary" @click="clear">New Purchase</el-button></span></el-dialog></template>
<script>
import {listConfigs,listUsers,quotePurchase,purchase,requestKey,money} from '@/api/commerce'
import {dateTime} from '@/utils/format'
import {creditGrantLabel} from '@/utils/entitlements'
export default{props:{visible:Boolean,userId:String},data(){return{users:[],products:[],selectedUser:'',productId:'',skuId:'',outcome:'succeeded',quote:null,result:null,error:'',busy:false,key:''}},computed:{skus(){const product=this.products.find(p=>p.id===this.productId);return product?product.published.skus.filter(s=>s.status==='active'):[]}},watch:{visible(value){if(value)this.load()}},methods:{money,dateTime,creditGrantLabel,clear(){this.quote=null;this.result=null;this.error='';this.key=''},selectProduct(){this.clear();this.skuId=this.skus.length?this.skus[0].id:''},async load(){this.clear();this.users=await listUsers();this.products=(await listConfigs('products')).filter(p=>p.published&&p.published.status==='active');this.selectedUser=this.userId||this.users[0].id;this.productId=this.products.length?this.products[0].id:'';this.selectProduct()},async review(){this.busy=true;try{this.quote=await quotePurchase({userId:this.selectedUser,productId:this.productId,skuId:this.skuId,subscriptionTimeZone:Intl.DateTimeFormat().resolvedOptions().timeZone});this.key=requestKey()}catch(e){this.error=e.message}finally{this.busy=false}},async confirm(){this.busy=true;try{this.result=await purchase({userId:this.selectedUser,quoteId:this.quote.id,outcome:this.outcome,requestKey:this.key});this.$emit('changed')}catch(e){this.error=e.message;if(['QUOTE_STALE','QUOTE_EXPIRED'].includes(e.reason))this.quote=null}finally{this.busy=false}}}}
</script>
